import type{MedusaRequest,MedusaResponse}from'@medusajs/framework/http';import{ContainerRegistrationKeys,Modules}from'@medusajs/framework/utils';
const states=['under_review','processing','shipping','delivered'];const aid=(r:any)=>r.auth_context?.actor_id||r.auth_context?.auth_identity_id;
async function seller(req:any,a:string){const q=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;const {data}=await q.graph({entity:'seller_member',fields:['seller.id','seller.name'],filters:{member_id:a},pagination:{take:1}}).catch(()=>({data:[]}));return data?.[0]?.seller||null}
export async function POST(req:MedusaRequest,res:MedusaResponse){const a=aid(req),s=await seller(req,a);if(!s)return res.status(403).json({message:'Seller not found'});const status=String((req.body as any)?.status||'');if(!states.includes(status))return res.status(422).json({message:'حالة الطلب غير صالحة'});const q=req.scope.resolve(ContainerRegistrationKeys.QUERY) as any;const {data}=await q.graph({entity:'order',fields:['id','currency_code','customer_id','metadata','items.id','items.total','items.unit_price','items.quantity','items.offer.seller_id'],filters:{id:req.params.id},pagination:{take:1}});const o=data?.[0];if(!o)return res.status(404).json({message:'Order not found'});const items=(o.items||[]).filter((i:any)=>i.offer?.seller_id===s.id);if(!items.length)return res.status(403).json({message:'هذا الطلب لا يخص متجرك'});const before=o.metadata?.[`spike_seller_status_${s.id}`]||'under_review';const meta={...(o.metadata||{}),[`spike_seller_status_${s.id}`]:status};await (req.scope.resolve(Modules.ORDER) as any).updateOrders(req.params.id,{metadata:meta});const sp=req.scope.resolve('spike') as any;await sp.createSpikeAuditLogs({actor_id:a,actor_type:'seller',action:'order_status_changed',entity_type:'order',entity_id:o.id,before:{status:before},after:{status}});if(o.customer_id)await sp.createSpikeNotifications({audience:'customer',customer_id:o.customer_id,type:'order_status',title:status==='processing'?'طلبك قيد التجهيز':status==='shipping'?'طلبك قيد التوصيل':status==='delivered'?'تم توصيل طلبك':'طلبك قيد المراجعة',body:`تم تحديث حالة جزء الطلب الخاص بمتجر ${s.name||''}`,entity_type:'order',entity_id:o.id,read:false});if(status==='delivered'&&before!=='delivered'){const subtotal=items.reduce((n:number,i:any)=>n+Number(i.total??Number(i.unit_price||0)*Number(i.quantity||1)),0);const set=await sp.listSpikeSettings({key:'commission_percent'},{take:1});const pct=Number(set[0]?.value??5);const amount=subtotal*(1-pct/100);await sp.createSpikePayables({kind:'seller',beneficiary_id:s.id,beneficiary_name:s.name||null,order_id:o.id,reference_id:`seller:${s.id}`,amount,currency_code:o.currency_code||'YER',status:'pending',note:`صافي بعد عمولة Spike ${pct}%`})}res.json({status})}
